                MCinvoke(MCwindow,"MCshowSettings");ComboBox<String> MCscope=MCvalue(MCwindow,"MCexportScope");ComboBox<MCTemplate> MCtemplates=MCvalue(MCwindow,"MCexportTemplate");ComboBox<MCTemplateGroup> MCgroups=MCvalue(MCwindow,"MCexportGroup");
