                    Button MCimporting=MCwindow.MCroot().lookupAll(".button").stream().filter(MCn->MCn instanceof Button MCb&&MCb.getText().equals("Importar archivo (.zip)")).map(MCn->(Button)MCn).findFirst().orElseThrow();
                    assertThat(MCimporting.getStyleClass()).contains("button","primary-btn");assertThat(MCimporting.getMinHeight()).isGreaterThanOrEqualTo(36);assertThat(MCimporting.getBackground()).isNotNull();
                    VBox MCsidebar=MCvalue(MCwindow,"MCsidebar");assertThat(MCsidebar.getPrefWidth()).isEqualTo(242);
