    @Test void MCgenerationUsesLocalExtrasThenSavesManualChangesAndApiResultsWithoutConfirmation()throws Exception{
        MCDocumentStore MCstore=new MCDocumentStore(MCtemp);MCStudioData MCdata=new MCStudioData(MCtemp);MCApiCredentialStore MCvault=new MCApiCredentialStore(MCtemp);MCvault.MCadd("Prueba","Factiliza","fixture-token");
        MCTemplate MCtemplate=MCtemplate(MCstore,"Carta","{{dni}} {{nombre}} {{direccion}} {{ubigeo}}");
        MCTemplateGroup MCgroup=MCstore.MCsaveGroup(0,"Cartas");MCstore.MCsetTemplateGroups(MCtemplate.MCid(),List.of(MCgroup.MCid()));
        List<MCVariable> MCvariables=new ArrayList<>();int MCposition=1;
        for(String MCkey:List.of("dni","nombre","direccion","ubigeo"))MCvariables.add(MCstore.MCsaveVariable(new MCVariable(0,MCtemplate.MCid(),MCkey,MCkey,switch(MCkey){case "dni"->"DNI";case "direccion"->"Domicilio";default->"Texto corto";},"",false,MCposition++)));
        for(MCVariable MCv:MCvariables)MCdata.MCsaveApiBinding(new MCApiBinding(MCstore.MCdefinitionId(MCv.MCid()),"DNI","field:"+switch(MCv.MCkey()){case "dni"->"numero";case "nombre"->"nombres";case "direccion"->"direccion";default->"ubigeo";}));
        MCdata.MCsaveContact(new MCContact(0,"Persona","Ana","Pérez","DNI","12345678","Lima","","{\"ubigeo\":\"150101\",\"data.extra\":\"valor\"}"));
        AtomicInteger MCcalls=new AtomicInteger();AtomicReference<Map<String,String>> MCresponse=new AtomicReference<>(Map.of("data.numero","87654321","data.nombres","María","data.apellido_paterno","Ruiz","data.direccion","Cusco","data.ubigeo[2]","080101","data.extra","conservado"));
        MCLookupProvider MCprovider=new MCLookupProvider(){public String MCname(){return "Factiliza";}public Set<String> MCservices(){return Set.of("DNI","RUC");}public Map<String,String> MCquery(String MCservice,String MCidentifier,String MCtoken){MCcalls.incrementAndGet();return MCresponse.get();}};
        MCLookupRouter MCrouter=new MCLookupRouter(MCvault,List.of(MCprovider));
        MCStudioWindow MCwindow=MCfx(()->{Stage MCstage=new Stage();MCStudioWindow MCcreated=new MCStudioWindow(MCstage,MCstore,MCrouter);MCstage.setScene(MCscene(MCcreated));return MCcreated;});
        try{
            MCfx(()->{
                MCinvoke(MCwindow,"MCshowGenerator");ComboBox<MCTemplate> MCtemplates=MCvalue(MCwindow,"MCgenerateTemplate");MCtemplates.getSelectionModel().selectFirst();MCinvoke(MCwindow,"MCbuildDynamicForm");MCTemplate MCselected=MCtemplates.getValue();Map<String,Control> MCfields=MCvalue(MCwindow,"MCinputs");
                TextField MCdni=(TextField)MCfields.get("dni");MCdni.setText("12345678");
                MCinvoke(MCwindow,"MClookupForField",new Class<?>[]{MCTemplate.class,MCVariable.class,TextField.class,String.class},MCselected,MCvariables.get(0),MCdni,"DNI");
                assertThat(MCcalls).hasValue(0);assertThat(((TextField)MCfields.get("nombre")).getText()).isEqualTo("Ana");assertThat(((TextArea)MCfields.get("direccion")).getText()).isEqualTo("Lima");assertThat(((TextField)MCfields.get("ubigeo")).getText()).isEqualTo("150101");assertThat(((Label)MCvalue(MCwindow,"MCstatus")).getText()).isEqualTo("Datos cargados desde Clientes locales");
                ((TextField)MCfields.get("nombre")).setText("Ana actualizada");((TextArea)MCfields.get("direccion")).setText("Arequipa");MCinvoke(MCwindow,"MCmakePreview");assertThat((byte[])MCvalue(MCwindow,"MCgeneratedBytes")).isNotEmpty();
                MCContact MCsaved=MCdata.MCmatchingContact("Persona","DNI","12345678");assertThat(MCsaved.MCgiven()).isEqualTo("Ana actualizada");assertThat(MCsaved.MCaddress()).isEqualTo("Arequipa");assertThat(MCsaved.MCextrasJson()).contains("150101","data.extra");MCwindow.MCroot().applyCss();MCwindow.MCroot().layout();MCsnapshot(MCwindow,"generator-with-data");return null;
            });
            CompletableFuture<MCLookupRouter.MCResult> MCqueried=new CompletableFuture<>();MCfx(()->{MCinvoke(MCwindow,"MCrunApiQuery",new Class<?>[]{String.class,String.class,Long.class,Consumer.class},"DNI","87654321",null,(Consumer<MCLookupRouter.MCResult>)MCr->{try{MCinvoke(MCwindow,"MCshowApiResult",new Class<?>[]{MCLookupRouter.MCResult.class},MCr);MCqueried.complete(MCr);}catch(Exception MCe){MCqueried.completeExceptionally(MCe);}});return null;});MCqueried.get(20,TimeUnit.SECONDS);
            MCContact MCsaved=MCdata.MCmatchingContact("Persona","DNI","87654321");assertThat(MCsaved.MCgiven()).isEqualTo("María");assertThat(MCsaved.MCfamily()).isEqualTo("Ruiz");assertThat(MCsaved.MCextrasJson()).contains("data.extra","conservado","080101");
            MCfx(()->{assertThat(((Label)MCvalue(MCwindow,"MCapiSaved")).getText()).isEqualTo("✓ Guardado automáticamente en Clientes");return null;});assertThat(MCdata.MCcontacts()).hasSize(2);
        }finally{MCfx(()->{((Stage)MCvalue(MCwindow,"MCstage")).close();return null;});}
    }

    @Test void MCopeningAndPrintingSaveNamedIdentifierFormsAndAllExtrasBeforeDispatch()throws Exception{
        MCDocumentStore MCstore=new MCDocumentStore(MCtemp);MCStudioData MCdata=new MCStudioData(MCtemp);MCTemplate MCtemplate=MCtemplate(MCstore,"Documento","{{documento}} {{cliente}} {{apellidos}} {{direccion}} {{referencia}}");MCTemplateGroup MCgroup=MCstore.MCsaveGroup(0,"Documentos");MCstore.MCsetTemplateGroups(MCtemplate.MCid(),List.of(MCgroup.MCid()));
        for(String MCkey:List.of("documento","cliente","apellidos","direccion","referencia"))MCstore.MCsaveVariable(new MCVariable(0,MCtemplate.MCid(),MCkey,MCkey.equals("documento")?"DNI del cliente":MCkey,"Texto corto","",false,1));
        List<Path> MCopened=new ArrayList<>(),MCprinted=new ArrayList<>();MCStudioWindow.MCDocumentActions MCactions=new MCStudioWindow.MCDocumentActions(){
            public void MCopen(Path MCfile)throws Exception{assertThat(MCdata.MCmatchingContact("Persona","DNI","12345678").MCgiven()).isEqualTo("Ana");MCopened.add(MCfile);}
            public void MCprint(Path MCfile)throws Exception{assertThat(MCdata.MCmatchingContact("Persona","DNI","12345678").MCgiven()).isEqualTo("Ana nueva");MCprinted.add(MCfile);}
        };
        MCfx(()->{
            Stage MCstage=new Stage();MCStudioWindow MCwindow=new MCStudioWindow(MCstage,MCstore,null,MCactions);MCstage.setScene(MCscene(MCwindow));
            try{
                MCinvoke(MCwindow,"MCshowGenerator");ComboBox<MCTemplate> MCchoices=MCvalue(MCwindow,"MCgenerateTemplate");MCchoices.getSelectionModel().selectFirst();MCinvoke(MCwindow,"MCbuildDynamicForm");Map<String,Control> MCfields=MCvalue(MCwindow,"MCinputs");
                ((TextField)MCfields.get("documento")).setText("12345678");((TextField)MCfields.get("cliente")).setText("Ana");((TextField)MCfields.get("apellidos")).setText("Pérez");((TextField)MCfields.get("direccion")).setText("Lima");((TextField)MCfields.get("referencia")).setText("Puerta azul");
                MCinvoke(MCwindow,"MCopenGeneratedInWord");assertThat(MCopened).hasSize(1);assertThat(MCopened.get(0).getFileName().toString()).startsWith("documento-").endsWith(".docx");try(XWPFDocument MCdoc=MCDocumentEngine.MCopen(Files.readAllBytes(MCopened.get(0)))){assertThat(MCdoc.getParagraphs().get(0).getText()).contains("Ana","Puerta azul");}
                ((TextField)MCfields.get("cliente")).setText("Ana nueva");((TextField)MCfields.get("referencia")).setText("Puerta verde");MCinvoke(MCwindow,"MCprintGenerated");assertThat(MCprinted).hasSize(1);assertThat(Files.readAllBytes(MCprinted.get(0))).startsWith("%PDF-".getBytes(java.nio.charset.StandardCharsets.US_ASCII));
                assertThat(MCdata.MCcontacts()).hasSize(1);MCContact MCcontact=MCdata.MCmatchingContact("Persona","DNI","12345678");assertThat(new com.fasterxml.jackson.databind.ObjectMapper().readTree(MCcontact.MCextrasJson()).path("referencia").asText()).isEqualTo("Puerta verde");
                ((TextField)MCfields.get("documento")).clear();((TextField)MCfields.get("cliente")).clear();((TextField)MCfields.get("referencia")).clear();((TextField)MCfields.get("documento")).setText("12345678");assertThat(((TextField)MCfields.get("cliente")).getText()).isEqualTo("Ana nueva");assertThat(((TextField)MCfields.get("referencia")).getText()).isEqualTo("Puerta verde");
                MCinvoke(MCwindow,"MCshowContacts");MCwindow.MCroot().applyCss();MCwindow.MCroot().layout();((Button)MCvalue(MCwindow,"MCclientDetailsToggle")).fire();MCwindow.MCroot().applyCss();MCwindow.MCroot().layout();assertThat(MCbuttonLabels((BorderPane)MCvalue(MCwindow,"MCcontactsPage"))).containsExactlyInAnyOrder("Guardar cliente","Eliminar cliente","Nueva persona","Asignar / Actualizar","Quitar","Volver a documentos");ListView<MCContact> MCclients=MCvalue(MCwindow,"MCcontactList");assertThat(MCclients.getItems()).hasSize(1);assertThat(MCclients.getSelectionModel().getSelectedItem()).isNotNull();
                ((TextField)MCvalue(MCwindow,"MCcontactGiven")).setText("Editada en Clientes");MCinvoke(MCwindow,"MCsaveContact");assertThat(MCdata.MCcontacts()).hasSize(1);assertThat(MCdata.MCmatchingContact("Persona","DNI","12345678").MCgiven()).isEqualTo("Editada en Clientes");
                TextField MCsearch=MCvalue(MCwindow,"MCcontactSearch");MCsearch.setText("inexistente");assertThat(MCclients.getItems()).isEmpty();MCsearch.clear();assertThat(MCclients.getItems()).hasSize(1);MCinvoke(MCwindow,"MCdeleteContact");assertThat(MCdata.MCcontacts()).isEmpty();
            }finally{MCstage.close();for(Path MCfile:MCopened)Files.deleteIfExists(MCfile);for(Path MCfile:MCprinted)Files.deleteIfExists(MCfile);}return null;
        });
    }

