    @Test void MCdeletingTemplateRequiresConfirmationAndKeepsGeneratedDocuments()throws Exception{
        MCDocumentStore MCstore=new MCDocumentStore(MCtemp);MCStudioData MCdata=new MCStudioData(MCtemp);MCTemplate MCtemplate=MCtemplate(MCstore,"Carta","Documento");MCdata.MCsaveHistory(new MCHistory(0,"Carta generada",MCtemplate.MCid(),1,null,"{}",null,null,MCtemplate.MCedited(),null));
        MCfx(()->{
            Stage MCstage=new Stage();MCStudioWindow MCwindow=new MCStudioWindow(MCstage,MCstore);MCstage.setScene(MCscene(MCwindow));
            try{
                MCinvoke(MCwindow,"MCshowLibrary");ListView<MCTemplate> MCcatalog=MCvalue(MCwindow,"MClibraryList");MCcatalog.getSelectionModel().selectFirst();
                AtomicReference<Throwable> MCproblem=MCanswerDialog(ButtonType.CANCEL,MCpane->{assertThat(MCpane.getContentText()).contains("Historial","conservarán");assertThat(MCstore.MCtemplates()).hasSize(1);});
                MCinvoke(MCwindow,"MCremoveLibraryTemplate");assertThat(MCproblem.get()).isNull();assertThat(MCstore.MCtemplates()).hasSize(1);assertThat(MCdata.MChistory().get(0).MCtemplateId()).isEqualTo(MCtemplate.MCid());
                MCproblem=MCanswerDialog(ButtonType.YES,MCpane->{assertThat(MCpane.getContentText()).contains("Carta","Historial");assertThat(MCstore.MCtemplates()).hasSize(1);});
                MCinvoke(MCwindow,"MCremoveLibraryTemplate");assertThat(MCproblem.get()).isNull();assertThat(MCstore.MCtemplates()).isEmpty();assertThat(MCdata.MChistory()).hasSize(1);assertThat(MCdata.MChistory().get(0).MCtemplateId()).isNull();assertThat(MCdata.MChistory().get(0).MCdocx()).containsExactly(MCtemplate.MCedited());
            }finally{MCstage.close();}return null;
        });
    }

